// 发送POST请求获取数据
let response = java.ajax(
  `${source.sourceUrl}/getDataInit,` + JSON.stringify({
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
      name: 'John',
      age: 31,
      city: 'New York'
    })
  })
);

// 解析响应并获取域名配置
const responseData = JSON.parse(response);
const domains = responseData.data.macVodLinkMap;

// 新增日志输出macVodLinkMap内容
java.log("macVodLinkMap内容: " + JSON.stringify(domains, null, 2));

const serverId = "{{$.data.result.vod_server_id}}";
const posterUrl = "{{java.get('pic')}}";

// 从海报URL提取主域名
const extractDomain = (url) => url.match(/^(https?:\/\/[^/?#]+)/)?.[1] || "";

// 选择域名：优先使用LINK_2配置域名，否则使用海报主域名
const domain = domains?.[serverId]?.LINK_2 || extractDomain(posterUrl);

// 构建播放器HTML
result = `
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1,minimum-scale=1,maximum-scale=1,user-scalable=no">
  <meta name="referrer" content="never"/>
  <style>
    html, body { text-align:center; margin:0; padding:0; width:100%; overflow:hidden; }
  </style>
</head>
<body>
  <div class="container">
    <div class="title">${serverId}*{{$.data.result.vod_name##yy8.*om}}</div>
    <video 
      id="video" 
      src="${domain}{{$.data.result.vod_url}}" 
      width="100%" 
      height="91%"
      poster="${posterUrl}"
      controls autoplay muted loop>
    </video>
  </div>
</body>
</html>
`;

