@js:
var page = org.jsoup.Jsoup.parse(result);
var code = page.select('#mac-player script').html();
var title = page.select('.z-current').html();
var text = page.select('.z-article-content').html();

if (text) {
    var textStr = String(text);
    var textWithoutImg = textStr.replace(/<img[^>]*>/gi, '');
    var textWithoutImgAndBr = textWithoutImg.replace(/<br\s*\/?>/gi, '');
    var plainText = textWithoutImgAndBr.replace(/<[^>]+>/g, '').trim();
    if (plainText === '') {
        text = textStr.replace(/<br\s*\/?>/gi, '');
    }
}

var textorimgTitle = page.select('.z-article-title').html();
var textorimgTime = page.select('.z-article-meta').html();

var imgs = page.select('#read_tpc img');
var imgsHtml = '';
for (var i = 0; i < imgs.size(); i++) {
    imgsHtml += imgs.get(i).outerHtml() + '\n';
}
if (!title) title = '内容详情';

var videoUrl = '';
if (code) {
    var urlMatch = code.match(/url\s*[:=]\s*["']([^"']+\.m3u8[^"']*)["']/i);
    if (urlMatch) {
        videoUrl = urlMatch[1];
    } else {
        var playerMatch = code.match(/player_aaaa\s*=\s*(\{[^;]+\})/);
        if (playerMatch) {
            try {
                var playerObj = JSON.parse(playerMatch[1]);
                if (playerObj.url && playerObj.url.indexOf('.m3u8') !== -1) {
                    videoUrl = playerObj.url;
                }
            } catch (e) {}
        }
    }
}

var hasVideo = videoUrl && 
               videoUrl.trim() !== '' && 
               /^https?:\/\/[^\s]+\.m3u8/i.test(videoUrl);

var subInfo = '';
if (textorimgTitle) {
    subInfo += '<div class="sub-title">' + textorimgTitle + '</div>';
}
if (textorimgTime) {
    subInfo += '<div class="meta-time">' + textorimgTime + '</div>';
}

if (hasVideo) {
    // 视频分支保持不变（全页滚动）
    result = `
<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no" />
    <title>${title}</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            background: #0d0d0d;
            font-family: system-ui, -apple-system, sans-serif;
            padding: 10px;
            color: #e0e0e0;
        }
        .player-container {
            max-width: 800px;
            margin: 0 auto;
            background: #1a1a2e;
            border-radius: 12px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.6);
            padding: 12px 12px;
            overflow: hidden;
        }
        .title {
            font-size: 16px;
            font-weight: 600;
            margin-bottom: 6px;
            color: #f0f0f0;
            line-height: 1.4;
            word-break: break-word;
        }
        .sub-title {
            font-size: 18px;
            color: #ccc;
            margin-bottom: 4px;
            word-break: break-word;
        }
        .meta-time {
            font-size: 14px;
            color: #999;
            margin-bottom: 12px;
        }
        .video-wrapper {
            width: 100%;
            background: #000;
            border-radius: 8px;
            overflow: hidden;
            position: relative;
            aspect-ratio: 16 / 9;
            max-height: 80vh;
        }
        .video-wrapper video {
            width: 100%;
            height: 100%;
            display: block;
            background: #000;
        }
        @supports not (aspect-ratio: 16/9) {
            .video-wrapper {
                padding-bottom: 56.25%;
                height: 0;
            }
            .video-wrapper video {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
        }
        .status {
            margin-top: 12px;
            padding: 12px;
            background: #16213e;
            border-radius: 6px;
            font-size: 16px;
            text-align: center;
            border: 1px solid #0f3460;
            color: #bbb;
        }
        .status.loading { color: #6ea8fe; }
        .status.error   { color: #f87171; }
        .status.ready   { color: #6fcf97; }
        .content {
            margin-top: 16px;
            font-size: 18px;
            line-height: 1.8;
            color: #ddd;
            word-break: break-word;
        }
        .content p {
            margin: 0 0 0.5em 0;
        }
        .content p:last-child {
            margin-bottom: 0;
        }
        .content img {
            max-width: 100%;
            height: auto;
            display: block;
            margin: 0;
            border-radius: 8px;
        }
        .content p:has(img) {
            margin: 0;
            line-height: 0;
        }
        .content img + img {
            margin-top: 0;
        }
    </style>
</head>
<body>
<div class="player-container">
    <div class="title">${title}</div>
    ${subInfo}
    <div class="video-wrapper">
        <video id="video" controls playsinline></video>
    </div>
    <div id="status" class="status">正在加载播放器...</div>
    <div class="content">${text ? text : ''}</div>
</div>
<script src="https://cdn.jsdelivr.net/npm/hls.js@1"></script>
<script>
    (function () {
        var videoSrc = '${videoUrl}';
        var video = document.getElementById('video');
        var statusDiv = document.getElementById('status');

        function updateStatus(msg, type) {
            statusDiv.textContent = msg;
            statusDiv.className = 'status' + (type ? ' ' + type : '');
        }

        if (Hls.isSupported()) {
            var hls = new Hls();
            hls.attachMedia(video);
            hls.on(Hls.Events.MANIFEST_PARSED, function () {
                updateStatus('视频已就绪，正在播放...', 'ready');
                video.play().catch(function () {
                    updateStatus('视频已就绪，请点击播放', 'ready');
                });
            });
            hls.on(Hls.Events.ERROR, function (event, data) {
                if (data.fatal) {
                    switch (data.type) {
                        case Hls.ErrorTypes.NETWORK_ERROR:
                            updateStatus('网络错误，尝试重连...', 'error');
                            hls.startLoad();
                            break;
                        case Hls.ErrorTypes.MEDIA_ERROR:
