function searchKey(page, source) {
    const {java} = this;
    let user_key = '';

    const svg = String(java.base64Encode(
        `
        <svg width="1400" height="500" xmlns="http://www.w3.org/2000/svg">
            <rect width="100%" height="100%" fill="#ffffff"/>
            <text x="200" y="150" font-family="Arial, sans-serif" font-size="80" fill="#1a1a1c">
                <tspan x="50" dy="30">在下方👇输入搜索的关键字：👇</tspan>
                <tspan font-size="68" fill="#f82148" x="20" dy="230">👇👇👇👇👇👇👇👇👇👇👇👇👇👇👇👇👇👇</tspan>
            </text>
        </svg>
        `

    ));

    if (page == 1) {
        try {
            // 通过验证码输入框获取到输入词
            user_key = java.getVerificationCode('data:image/svg+xml;base64,' + svg);

        } catch (error) {
            //未输入词，捕获异常，使用默认输入词
            user_key = '我的'
            java.log('搜索词未获取到，使用默认搜索词: 我的')
        }
        source.setVariable(user_key)
        java.log(
            [ '搜索词: ', user_key, '\n',
            '搜索词已通过setVariable保存'
            ].join('')
        )

    }else{
        user_key = source.getVariable();
        java.log('搜索词已通过getVariable得到')
    }

    java.log('搜索关键字为：' + user_key)


    return user_key;
}


// 输入搜索::https://url/search/page/{{page}}/wd/{{ searchKey(page, source) }}.html

