        <!-- 引入必要的JS库 -->
        <script src="https://cdn.jsdelivr.net/npm/jquery@3.6.0/dist/jquery.min.js"></script>
        <script src="https://cdn.jsdelivr.net/npm/video.js@7.20.3/dist/video.min.js"></script>
        <script src="https://cdn.jsdelivr.net/npm/@videojs/http-streaming@2.16.0/dist/videojs-http-streaming.min.js"></script>

        <script>
            // 全局变量存储播放器实例
            var player;
            // 初始化播放器
            function initPlayer() {
                // 检查是否已初始化
                var videoElement = document.getElementById('my-video');
                if (videoElement && videojs.getPlayers()['my-video']) {
                    return videojs.getPlayers()['my-video'];
                }

                // 创建新播放器实例
                player = videojs('my-video', {
                    controls: true,
                    autoplay: false,
                    muted: true,
                    preload: 'auto',
                    fluid: true,
                    aspectRatio: '16:9',
                    playbackRates: [0.5, 1, 1.5, 2],
                    html5: {
                        vhs: {
                            // 关键优化参数
                            overrideNative: true,
                            enableLowInitialPlaylist: true,
                            smoothQualityChange: true,           // 平滑质量切换，避免加载转圈
                            limitRenditionByPlayerDimensions: false, // 不限制分辨率，充分利用带宽

                            // 带宽估算优化
                            defaultBandwidthEstimate: 5000000,  // 提高到 5Mbps（原2Mbps可能过低）
                            useNetworkInformationApi: true,       // 使用网络信息API辅助估算

                            // 缓冲控制 - 关键优化！
                            maxBufferLength: 30,                  // 最大缓冲30秒（平衡内存和流畅度）
                            maxMaxBufferLength: 60,               // 绝对最大缓冲60秒
                            backBufferLength: 30,                 // 回看缓冲，避免频繁重新加载

                            // 低延迟优化
                            lowLatencyMode: false,                // 点播视频不需要低延迟模式

                            // 部分数据加载优化
                            handlePartialData: true,              // 启用部分数据追加，更快开始播放

                            // ABR (自适应码率) 优化
                            bandwidth: {
                                defaultBandwidthEstimate: 5000000
                            }
                        },
                        nativeCaptions: false,
                        nativeAudioTracks: false,
                        nativeVideoTracks: false
                    },
                    userActions: {
                        hotkeys: true
                    }
                });

                // 保存播放进度
                player.on('timeupdate', function() {
                    localStorage.setItem('video_last_position', player.currentTime());
                });

                // 恢复播放进度
                var lastPosition = localStorage.getItem('video_last_position');
                if (lastPosition) {
                    player.ready(function() {
                        player.currentTime(lastPosition);
                    });
                }

                // 监听视频元数据加载


                // 窗口大小变化时重新计算
                window.addEventListener('resize', function() {
                    if (player) {
                        player.aspectRatio(player.aspectRatio());
                    }
                });



                return player;
            }

            // 初始化设置面板
            function initSettings(player) {
                var settingsPanel = document.getElementById('settingsPanel');
                var overlay = document.getElementById('overlay');
                var settingsBtn = document.getElementById('settingsBtn');
                var closeSettings = document.getElementById('closeSettings');
                var saveSettings = document.getElementById('saveSettings');
                var themeSelect = document.getElementById('themeSelect');
                var volumeControl = document.getElementById('volumeControl');
                var autoplayCheck = document.getElementById('autoplayCheck');
                var muteCheck = document.getElementById('muteCheck');
                var loopCheck = document.getElementById('loopCheck');
                var skipIntro = document.getElementById('skipIntro');
                var skipOutro = document.getElementById('skipOutro');
                var lowLatencyCheck = document.getElementById('lowLatencyCheck');
                var autoQualityCheck = document.getElementById('autoQualityCheck');
                var themeOptions = document.querySelectorAll('.theme-option');
                var tabButtons = document.querySelectorAll('.settings-tab');
                var tabContents = document.querySelectorAll('.settings-content');

                // 从本地存储加载设置
                function loadSettings() {
                    var settings = JSON.parse(localStorage.getItem('player_settings')) || {};

                    // 主题设置
                    if (settings.theme) {
                        document.body.className = '';
                        document.body.classList.add('theme-' + settings.theme);
                        themeSelect.value = settings.theme;

                        // 更新主题选项的active状态
                        themeOptions.forEach(function(option) {
                            option.classList.remove('active');
                            if (option.dataset.theme === settings.theme) {
                                option.classList.add('active');
                            }
                        });
                    }

                    // 播放设置
                    if (settings.volume !== undefined) {
                        player.volume(settings.volume);
                        volumeControl.value = settings.volume;
                    }

                    if (settings.autoplay !== undefined) {
                        autoplayCheck.checked = settings.autoplay;
                    }

                    if (settings.mute !== undefined) {
                        muteCheck.checked = settings.mute;
                        player.muted(settings.mute);
                    }

                    if (settings.loop !== undefined) {
                        loopCheck.checked = settings.loop;
                        player.loop(settings.loop);
                    }

                    // 高级设置
                    if (settings.skipIntro !== undefined) {
                        skipIntro.value = settings.skipIntro;
                    }

                    if (settings.skipOutro !== undefined) {
                        skipOutro.value = settings.skipOutro;
                    }

                    if (settings.lowLatency !== undefined) {
                        lowLatencyCheck.checked = settings.lowLatency;
                    }

                    if (settings.autoQuality !== undefined) {
                        autoQualityCheck.checked = settings.autoQuality;
                    }
                }

                // 修改保存设置函数，添加跳过片头片尾逻辑
                function saveSettingsToStorage() {
                    var settings = {
                        theme: themeSelect.value,
                        volume: parseFloat(volumeControl.value),
                        autoplay: autoplayCheck.checked,
                        mute: muteCheck.checked,
                        loop: loopCheck.checked,
                        skipIntro: skipIntro.value ? parseInt(skipIntro.value) : 0,
                        skipOutro: skipOutro.value ? parseInt(skipOutro.value) : 0,
                        lowLatency: lowLatencyCheck.checked,
                        autoQuality: autoQualityCheck.checked
                    };

                    localStorage.setItem('player_settings', JSON.stringify(settings));
                    return settings;
                }

                // 切换标签页
                function switchTab(tabName) {
                    tabButtons.forEach(function(button) {
                        button.classList.remove('active');
                        if (button.dataset.tab === tabName) {
                            button.classList.add('active');
                        }
                    });

                    tabContents.forEach(function(content) {
                        content.classList.remove('active');
                        if (content.id === tabName + 'Settings') {
                            content.classList.add('active');
                        }
                    });
                }

                // 添加跳过片头片尾功能
                player.on('timeupdate', function() {
                    var settings = JSON.parse(localStorage.getItem('player_settings')) || {};
                    var skipIntro = settings.skipIntro || 0;
                    var skipOutro = settings.skipOutro || 0;
                    var duration = player.duration();

                    // 跳过片头
                    if (skipIntro > 0 && player.currentTime() < skipIntro) {
                        player.currentTime(skipIntro);
                    }

                    // 跳过片尾
                    if (skipOutro > 0 && duration > 0 && player.currentTime() > duration - skipOutro) {
                        player.currentTime(duration - skipOutro);
                        if (!player.paused()) {
                            player.pause();
                        }
                    }
                });

                // 事件监听
                settingsBtn.addEventListener('click', function() {
                    settingsPanel.classList.add('active');
                    overlay.classList.add('active');
                    document.body.style.overflow = 'hidden';
                });

                closeSettings.addEventListener('click', function() {
                    settingsPanel.classList.remove('active');
                    overlay.classList.remove('active');
                    document.body.style.overflow = '';
                });

                overlay.addEventListener('click', function() {
                    settingsPanel.classList.remove('active');
                    overlay.classList.remove('active');
                    document.body.style.overflow = '';
                });

                saveSettings.addEventListener('click', function() {
                    var settings = saveSettingsToStorage();

                    // 应用设置
                    document.body.className = '';
                    document.body.classList.add('theme-' + settings.theme);
                    player.volume(settings.volume);
                    player.muted(settings.mute);
                    player.loop(settings.loop);

                    // 关闭设置面板
                    settingsPanel.classList.remove('active');
                    overlay.classList.remove('active');
                    document.body.style.overflow = '';
                });

                // 主题选择
                themeSelect.addEventListener('change', function() {
                    var theme = this.value;
                    document.body.className = '';
                    document.body.classList.add('theme-' + theme);

                    // 更新主题选项的active状态
                    themeOptions.forEach(function(option) {
                        option.classList.remove('active');
                        if (option.dataset.theme === theme) {
                            option.classList.add('active');
                        }
                    });
                });

                // 主题选项点击
                themeOptions.forEach(function(option) {
                    option.addEventListener('click', function() {
                        var theme = this.dataset.theme;
                        themeSelect.value = theme;
                        document.body.className = '';
                        document.body.classList.add('theme-' + theme);

                        // 更新主题选项的active状态
                        themeOptions.forEach(function(opt) {
                            opt.classList.remove('active');
                        });
                        this.classList.add('active');
                    });
                });

                // 标签页切换
                tabButtons.forEach(function(button) {
                    button.addEventListener('click', function() {
                        switchTab(this.dataset.tab);
                    });
                });

                // 音量控制
                volumeControl.addEventListener('input', function() {
                    player.volume(this.value);
                });

                // 静音控制
                muteCheck.addEventListener('change', function() {
                    player.muted(this.checked);
                });

                // 加载设置
                loadSettings();
            }

            // 初始化应用
            function initApp() {
                // 确保只初始化一次
                if (!window.playerInitialized) {
                    var player = initPlayer();
                    initSettings(player);

                    // 检测系统主题偏好
                    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
                        document.body.classList.add('theme-dark');
                        document.getElementById('themeSelect').value = 'dark';
                    }

                    window.playerInitialized = true;
                }

            }


            // 点击按钮,输入跳过默认值
            function clickElem() {

                document.getElementById('skipIntro').value = ${data.start_time}
                document.getElementById('skipOutro').value = ${data.end_time}


            }

            // console.log(111)
            // 文档加载完成后初始化
            if (document.readyState === 'complete') {
                initApp();
                clickElem();
            } else {
                document.addEventListener('DOMContentLoaded', initApp);
                document.addEventListener('DOMContentLoaded', clickElem);
            }


            $(document).ready(function() {
                // 使用jquery发送每集的请求，提取播放直链
                function video(url) {
                    //使用jquery发送单个播放页面get请求，提取播放直链
                    $.get(url, function(result) {

                        let json = result.match(/${data.reg}/)[1];
                        let src_url = JSON.parse(json).url.replace(/\\\\/, '');

                        //document.querySelector('.video-title').innerHTML = src_url
                        document.querySelector('#m3u8_url').value = src_url

