            display: block;
        }

        .info-area {
            padding: 10px 12px;
            background-color: #1a1a1a;
            color: #fff;
            font-size: 14px;
        }

        .episodes-area {
            height: 400px;
            overflow-y: auto;
            background-color: #1a1a1a;
        }

        .episode-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 10px;
            padding: 14px 12px;
            background-color: #1a1a1a;
        }

        .episode-btn {
            display: block;
            text-align: center;
            padding: 10px 0;
            background-color: #2c2c2c;
            color: #f0f0f0;
            font-size: 16px;
            cursor: pointer;
            border: none;
            border-radius: 4px;
            transition: all 0.2s;
        }

        .episode-btn.active {
            background-color: #007aff;
            color: #fff;
        }

        .episode-btn:active {
            transform: scale(0.98);
        }
    </style>
</head>
<body>
<div class="player-container">
    <div class="video-area">
        <video id="videoPlayer" controls preload="metadata">
            <source src="" type="video/mp4">
        </video>
    </div>

    <div class="info-area" id="infoArea">
        当前播放：未选择
    </div>

    <div class="episodes-area">
        <div class="episode-grid" id="episodeGrid">
            ${result}
        </div>
    </div>
</div>

<script>
    const gridContainer = document.getElementById('episodeGrid');
    const infoArea = document.getElementById('infoArea');
    const links = gridContainer.querySelectorAll('a');
    let currentBtn = null;

    function setActiveButton(btn) {
        if (currentBtn) {
            currentBtn.classList.remove('active');
        }
        btn.classList.add('active');
        currentBtn = btn;
    }

    links.forEach(link => {
        const btn = document.createElement('button');
        const episodeText = link.textContent.trim();
        btn.textContent = episodeText;
        btn.className = 'episode-btn';
        const href = link.getAttribute('href');
        btn.setAttribute('data-href', href);
        btn.setAttribute('data-title', episodeText);
        btn.addEventListener('click', async function(event) {
            event.preventDefault();
            const url = this.getAttribute('data-href');
            const title = this.getAttribute('data-title');

            setActiveButton(this);
            infoArea.textContent = '当前播放：' + title + "/共" + links.length + "集";

            try {
                const response = await fetch(url);
                const html = await response.text();

                const m = html.match(/currentUrl = '([^']+)'/)[1];
                if (m) {
                    const videoUrl = m;
                    const videoPlayer = document.getElementById('videoPlayer');
                    videoPlayer.src = videoUrl;
                    videoPlayer.play();
                }
            } catch (error) {
                console.error('获取视频地址失败:', error);
            }
        });
        link.replaceWith(btn);
    });

    const firstBtn = document.querySelector('.episode-btn');
    if (firstBtn) {
        firstBtn.click();
    }
</script>
</body>
</html>
`

