`
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title></title>
    <script src="https://board.ledvelm.com/usr/themes/haijiao3/assets/__base/js/crypto-js.js"></script>
    <script>
        function convertKey(keyStr) {
            return CryptoJS.enc.Utf8.parse(keyStr.split("_").map(code => String.fromCharCode(parseInt(code))).join(""));
        }
        function decryptImage(encryptedData) {
            const key = convertKey("102_53_100_57_54_53_100_102_55_53_51_51_54_50_55_48");
            const iv = convertKey("57_55_98_54_48_51_57_52_97_98_99_50_102_98_101_49");

            const decrypted = CryptoJS.AES.decrypt(encryptedData, key, {
                iv: iv,
                mode: CryptoJS.mode.CBC,
                padding: CryptoJS.pad.Pkcs7
            });
            return decrypted.toString(CryptoJS.enc.Base64);
        }
        async function loadEncryptedImage(imgElement) {
            const encryptedUrl = imgElement.getAttribute('z-image-loader-url');
            if (!encryptedUrl) return;
            try {
                const response = await fetch(encryptedUrl);
                const blob = await response.blob();
                const reader = new FileReader();
                reader.readAsDataURL(blob);

                reader.onload = function (e) {
                    const base64Data = e.target.result.split(',').pop();
                    const contentType = e.target.result.split(':')[1].split(';')[0];

                    const decryptedBase64 = decryptImage(base64Data);
                    const dataUrl = 'data:' + contentType + ';base64,' + decryptedBase64;
                    imgElement.src = dataUrl;
                };
            } catch (error) {
                console.error('图片解密失败:', error);
            }
        }
        function processEncryptedImages() {
            const encryptedImages = document.querySelectorAll('img[z-image-loader-url]');
            encryptedImages.forEach(img => loadEncryptedImage(img));
        }
        document.addEventListener('DOMContentLoaded', processEncryptedImages);
    </script>
</head>
<body>
    ${result}
</body>
</html>
`
</js>

