        var t = line.trim();
        if (!t) return line;
        if (t.charAt(0) === '#') {
            var k = t.indexOf('URI=');
            if (k < 0) return line;
            var q1 = t.indexOf(String.fromCharCode(34), k);
            var q2 = q1 < 0 ? -1 : t.indexOf(String.fromCharCode(34), q1 + 1);
            if (q1 < 0 || q2 <= q1) return line;
            return t.substring(0, q1 + 1) + _abs(mu, t.substring(q1 + 1, q2)) + t.substring(q2);
        }
        return _abs(mu, t);
    }).join(_NL);
}
/* 手势：双击左右快进 / 中间暂停，长按右侧倍速，横向拖动 Seek（替代 Artplayer 的那套） */
function _bindControls(v) {
    var FFV = ${_ff}, TMZ = ${_tz}, RATIO = 0.${_lv};
    if (!(FFV > 0)) FFV = 3;
    if (!(TMZ > 0)) TMZ = 10;
    if (!(RATIO > 0)) RATIO = 0.3;
    var pt = null, sx = 0, stime = 0;
    function rect() { return v.getBoundingClientRect(); }
    v.addEventListener('dblclick', function (ev) {
        var r = rect(), x = ev.clientX - r.left;
        if (x < r.width / 3) v.currentTime = Math.max(0, v.currentTime - TMZ);
        else if (x > r.width * 2 / 3) v.currentTime = v.currentTime + TMZ;
        else { if (v.paused) v.play(); else v.pause(); }
    });
    v.addEventListener('touchstart', function (ev) {
        if (!ev.touches || !ev.touches.length) return;
        var r = rect(), x = ev.touches[0].clientX - r.left;
