        if (x > r.width * 0.72) pt = setTimeout(function () { v.playbackRate = FFV; _tip('⏩ ' + FFV + ' 倍速'); }, 500);
    }, { passive: true });
    v.addEventListener('touchmove', function (ev) {
        if (!ev.touches || !ev.touches.length) return;
        var r = rect(), x = ev.touches[0].clientX - r.left;
        if (Math.abs(x - sx) > 12) {
            if (pt) { clearTimeout(pt); pt = null; v.playbackRate = 1; }
            v.currentTime = Math.max(0, Math.min(v.duration || 0, stime + (x - sx) * RATIO));
        }
    }, { passive: true });
    function endTouch() { if (pt) { clearTimeout(pt); pt = null; } v.playbackRate = 1; }
    v.addEventListener('touchend', endTouch);
    v.addEventListener('touchcancel', endTouch);
}
