            if (!(keyword.length>1)) return;
            addHistoryItem(keyword);
            searchInput.value="";
            java.open("sort", JSON.stringify({ [keyword]: `data:;base64,{{java.base64Encode("/zh/fc_search/all"+"/${keyword}/"+page+".html")}},{"type":"18av"}` }));
        }
        
        ss.addEventListener('submit', function (event) {
            event.preventDefault();
            const formData = new FormData(ss);
            const key = formData.get('key');
            if (key) {
            	performSearch(key);
           } else {
           	searchInput.placeholder = "输入关键词，亲";
           searchInput.focus();}
        });
//const tt = new Intl.DateTimeFormat('zh-CN', {year: 'numeric', month: '2-digit', day: '2-digit'}).format(new Date()).replace(/\//g, '-');
const fl = {
	"中文字幕":`data:;base64,{{java.base64Encode("/zh/chinese_list/all/"+page+".html")}},{"type":"18av"}`,
		"高清无码":`data:;base64,{{java.base64Encode("/zh/uncensored_list/all/"+page+".html")}},{"type":"18av"}`,
