        	if (url) java.open("sort", JSON.stringify({ [n]: url}));
        	}

        ss.style.animation = `fadeIn 0.6s ease-out forwards`;
        document.querySelectorAll('#fl > div').forEach((child, index) => {
            child.style.animation = `fadeIn ${0.8 + index * 0.3}s ease-out forwards`;
        });

function loadHistory() {
 return JSON.parse(localStorage.getItem(HISTORY_KEY)) || [];
}
function saveHistory(history) {
localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
}
function addHistoryItem(keyword) {
            let history = loadHistory();
            history = history.filter(item => item !== keyword);
            history.unshift(keyword);
            if (history.length > MAX_HISTORY_ITEMS) {
                history = history.slice(0, MAX_HISTORY_ITEMS);
            }
            saveHistory(history);
            renderHistory();
        }
function removeHistoryItem(keyword) {
            let history = loadHistory();
            history = history.filter(item => item !== keyword);
            saveHistory(history);
            renderHistory();
        }
function clearHistory() {
            if (confirm('确定要清除所有搜索历史吗？')) {
                localStorage.removeItem(HISTORY_KEY);
                renderHistory();
            }
        }
// 显示历史
        function renderHistory() {
            const history = loadHistory();
            historyList.innerHTML = '';
            if (history.length === 0) {
                historyList.innerHTML = '<div class="no-history">暂无搜索历史</div>';
                return;
            }

            history.forEach(keyword => {
                const item = document.createElement('div');
                item.className = 'history-item';
                item.innerHTML = `${keyword}<span class="fa-times" data-keyword="${keyword}">🗑️</span>`;
                historyList.appendChild(item);

                // 点击搜索
                item.addEventListener('click', (e) => {
                    if (!e.target.classList.contains('fa-times')) {
                        searchInput.value = keyword;
                        performSearch(keyword);
                    }
                });

                // 处理删除按钮
                const deleteBtn = item.querySelector('.fa-times');
                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    removeHistoryItem(keyword);
                });
            });
        }

clearHistoryBtn.addEventListener('click',clearHistory);        
renderHistory();

