<js>
var rawMatch = result.match(/const\s+rawUrl\s*=\s*['"]([^'"]*\.m3u8[^'"]*)['"]/i);
var vodUrl = rawMatch ? rawMatch[1].replace(/\\/g,'') : '';
// 如果上面没匹配到，再试试直接搜 .m3u8 链接
if (!vodUrl) {
    var m = result.match(/https?:\/\/[^\s"'<>]+\.m3u8[^\s"'<>]*/i);
    vodUrl = m ? m[0] : '';
}
var title = '@get:{t}';
var tags = java.getString('[property="video:tag"]@content');
var sign1 = java.base64Decode('');
var sign2 = java.base64Decode('');
var sign3 = java.base64Decode('');
`<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,sans-serif;background:#f0f9ff;padding:10px}
.v-box{max-width:800px;margin:0 auto;background:white;border-radius:12px;box-shadow:0 5px 15px rgba(0,0,0,0.1);overflow:hidden}
.header{padding:12px;border-bottom:1px solid #eee;display:flex;flex-wrap:wrap;justify-content:space-between}
.sign{background:#e9f7ff;padding:6px;border-radius:6px;margin-bottom:8px;font-size:14px;color:#1a73e8;width:100%}
.title{font-size:18px;font-weight:600;margin-bottom:8px;width:100%}
.tags{color:#5f6368;font-size:14px;flex:1;min-width:60%;word-break:break-all}
.time{color:#5f6368;font-size:14px;text-align:right;flex-basis:35%}
.v-wrap{position:relative;padding-top:56.25%;background:#000}
.video{position:absolute;top:0;left:0;width:100%;height:100%}
.footer{padding:8px;text-align:center;color:#5f6368;font-size:13px}
.info-box{padding:15px;font-size:14px;line-height:1.6}
.info-box p{margin:8px 0}
.hint{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(0,0,0,0.7);color:#fff;padding:12px 20px;border-radius:20px;font-size:1.1rem;z-index:10;display:none}
.controls{position:absolute;top:0;left:0;width:100%;height:4px;background:rgba(255,255,255,0.3);z-index:5;transition:opacity 0.3s}
.progress{height:100%;background:#4a9eff;width:0}
</style>
<script src="https://cdn.jsdelivr.net/npm/hls.js@latest"></script>
</head>
<body>
<div class="v-box">
<div class="header">
<div class="sign" style="text-align:center;padding:5px 0">
<div>${sign1}</div>
<div style="text-align:left; padding-top:4px">
${sign2}<br>${sign3}</div>
</div>
<div class="title">${title}</div>
<div class="tags">${tags}</div>
<div class="time" id="timeDisplay">00:00/00:00</div></div>
<div class="v-wrap">
<div class="controls"><div class="progress" id="progressBar"></div></div>
<div class="hint" id="hint">快进中 &gt;&gt;</div>
<video class="video" id="v" controls playsinline></video>
</div>
<div class="footer">滑动调整进度 | 长按2倍速</div>
</div>
<script>
var video = document.getElementById('v');
var videoSrc = '${vodUrl}';
var tDisplay = document.getElementById('timeDisplay');
var pBar = document.getElementById('progressBar');
var hint = document.getElementById('hint');
var startX = 0, startTime = 0;
var longPressTimer;
var sensitivity = 0.1;
var longPressTime = 500;
var hintDuration = 2000;

function updateTime() {
    if (!video.duration) return;
    var m1 = Math.floor(video.currentTime / 60);
    var s1 = Math.floor(video.currentTime % 60);
    var m2 = Math.floor(video.duration / 60);
    var s2 = Math.floor(video.duration % 60);
    tDisplay.textContent = m1 + ':' + (s1 < 10 ? '0' : '') + s1 + '/' + m2 + ':' + (s2 < 10 ? '0' : '') + s2;
    pBar.style.width = (video.currentTime / video.duration) * 100 + '%';
}

// HLS 支持
if (videoSrc && videoSrc.indexOf('.m3u8') > -1) {
    if (Hls.isSupported()) {
        var hls = new Hls();
        hls.loadSource(videoSrc);
        hls.attachMedia(video);
        hls.on(Hls.Events.MANIFEST_PARSED, function() {
            video.play();
        });
    } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
        video.src = videoSrc;
        video.addEventListener('loadedmetadata', function() {
            video.play();
        });
    } else {
        console.error('浏览器不支持 HLS 播放');
        alert('当前环境不支持播放此视频格式');
    }
} else {
    video.src = videoSrc;
}

video.addEventListener('timeupdate', updateTime);
video.addEventListener('loadedmetadata', updateTime);
video.addEventListener('touchstart', function(e) {
    startX = e.touches[0].clientX;
    startTime = Date.now();
    if (longPressTimer) clearTimeout(longPressTimer);
    hint.style.display = 'none';
    longPressTimer = setTimeout(function() {
        video.playbackRate = 2.0;
        hint.style.display = 'block';
        setTimeout(function() { hint.style.display = 'none'; }, hintDuration);
    }, longPressTime);
});
video.addEventListener('touchmove', function(e) {
    e.preventDefault();
    clearTimeout(longPressTimer);
    var diffX = e.touches[0].clientX - startX;
    var change = diffX * sensitivity * video.duration / 100;
    video.currentTime = Math.max(0, Math.min(video.currentTime + change, video.duration));
    startX = e.touches[0].clientX;
    updateTime();
});
video.addEventListener('touchend', function() {
    video.playbackRate = 1.0;
    clearTimeout(longPressTimer);
});
</script>
</body>
</html>`
</js>

